tool_input.command:
CLI=$PWD/packages/frai-cli/dist/index.js
node $CLI scan examples/support-triage-demo; echo "exit=$?"
node $CLI scan examples/support-triage-demo --json | head -20; echo "exit=$?"
node $CLI scan does/not/exist; echo "exit=$?"
node $CLI scan README.md; echo "exit=$?"
T=$(mktemp -d); mkdir -p $T/src; printf "import Anthropic from '@anthropic-ai/sdk';\nimport { ChatOpenAI } from '@langchain/openai';\n" > $T/src/llm.mts
(cd $T && node $CLI scan); echo "exit=$?"
node --input-type=module -e "
process.chdir('$PWD/examples');
const { scanRepositoryTool } = await import('$PWD/packages/frai-agent/dist/tools/scan-tool.js');
console.log(await scanRepositoryTool.invoke({ root: 'support-triage-demo' }));
console.log(await scanRepositoryTool.invoke({ root: 'nope' }));
"; rm -rf $T

node --input-type=module -e "
import { scanCodebase } from './packages/frai-core/src/scanners/index.js';
console.time('repo');
const r = scanCodebase({ root: '.' });
console.timeEnd('repo');
for (const [f, libs] of Object.entries(r.aiLibraryMatches)) console.log(f.replace(process.cwd() + '/', ''), libs);
"; rm /tmp/frai-e2e-check.sh
